"App installation data, i.e. where APKs go.": "بيانات تثبيت التطبيقات، أي المكان الذي تذهب إليه ملفات APK.",
"App libraries": "مكتبات التطبيقات",
"App operation": "عملية التطبيق",
"App ops need ADB, Shizuku or Root. Set up a working mode first.": "تتطلب App Ops وجود ADB أو Shizuku أو Root. أعدّ وضع تشغيل أولًا.",
"App page on device": "صفحة التطبيق على الجهاز",
"App related library data.": "بيانات المكتبات المتعلقة بالتطبيقات.",
"App shortcut icons": "أيقونات اختصارات التطبيقات",
"App sources": "مصادر التطبيقات",
"App that waits for a debugger (developer option)": "التطبيق الذي ينتظر مصحّح الأخطاء (خيار للمطوّرين)",
"App update": "تحديث التطبيق",
"App update failed": "فشل تحديث التطبيق",
"App updated": "تم تحديث التطبيق",
"App-specific": "خاصة بالتطبيق",
"App: ADB Application Manager Pro ? (build ?)": "التطبيق: ADB Application Manager Pro ? (الإصدار ?)",
"AppCleaner can clear the caches that no file access can reach (the \"Clear cache\" button of an app's Storage screen) by tapping through the system settings for you. For that it needs this app's accessibility service. The service only acts while AppCleaner is clearing caches: it opens the App info screen of one app after the other, taps Clear cache, and stops when the screen turns off or locks. A cover over the screen shows what it is doing, with a way to cancel. Nothing is read or sent anywhere. On Android 13 and newer, an app installed from a file may first need \"Allow restricted settings\" (App info of this app, the three dots menu).": "يستطيع AppCleaner مسح ذاكرات التخزين المؤقت التي لا يصل إليها أي وصول إلى الملفات (زر «مسح ذاكرة التخزين المؤقت» في شاشة التخزين لتطبيق ما) عبر الضغط في إعدادات النظام نيابةً عنك. لذلك يحتاج إلى خدمة إمكانية الوصول الخاصة بهذا التطبيق. لا تعمل الخدمة إلا أثناء مسح AppCleaner لذاكرات التخزين المؤقت: تفتح شاشة معلومات التطبيق لتطبيق بعد آخر، وتضغط على مسح ذاكرة التخزين المؤقت، وتتوقف عند انطفاء الشاشة أو قفلها. يعرض غطاء فوق الشاشة ما تفعله، مع طريقة للإلغاء. لا يُقرأ شيء ولا يُرسل إلى أي مكان. في Android 13 وما بعده، قد يحتاج التطبيق المثبّت من ملف أولًا إلى «السماح بالإعدادات المقيّدة» (معلومات التطبيق لهذا التطبيق، قائمة النقاط الثلاث).",
