"Aurora Store is an open-source Play Store client. Automatic Play version detection is a planned follow-up (it needs anonymous Play authentication); for now this routes each app to its store page, opening Aurora Store when it's installed.": "Aurora Store عميل مفتوح المصدر لمتجر Play Store. الكشف التلقائي عن إصدار Play ميزة مخطط لها لاحقًا (تتطلب مصادقة Play مجهولة)؛ وحاليًا يوجّه كل تطبيق إلى صفحته في المتجر، ويفتح Aurora Store إذا كان مثبّتًا.",
"Aurora Store: installed · Play Store: installed. Tap an app below to open its store page.": "Aurora Store: مثبّت · Play Store: مثبّت. انقر على تطبيق أدناه لفتح صفحته في المتجر.",
"Aurora Store: installed · Play Store: not installed. Tap an app below to open its store page.": "Aurora Store: مثبّت · Play Store: غير مثبّت. انقر على تطبيق أدناه لفتح صفحته في المتجر.",
"Aurora Store: not installed · Play Store: installed. Tap an app below to open its store page.": "Aurora Store: غير مثبّت · Play Store: مثبّت. انقر على تطبيق أدناه لفتح صفحته في المتجر.",
"Aurora Store: not installed · Play Store: not installed. Tap an app below to open its store page.": "Aurora Store: غير مثبّت · Play Store: غير مثبّت. انقر على تطبيق أدناه لفتح صفحته في المتجر.",
