"Changing the theme and the overlays goes through the shell. Connect one of them in Working Modes, then come back.": "يتم تغيير السمة والطبقات عبر Shell. اتصل بأحد الأوضاع في «أوضاع التشغيل» ثم عد.",
"Changing the theme and the overlays goes through the shell. Connect one of them in Working Modes, then come back. The colors in use now are shown without it.": "يتم تغيير السمة والطبقات عبر Shell. اتصل بأحد الأوضاع في «أوضاع التشغيل» ثم عد. تُعرض الألوان المستخدمة حاليًا دون ذلك.",
"Changing this can break setup, apps or the system. Only change it if you know what it does.": "قد يؤدي تغيير هذا إلى تعطّل الإعداد أو التطبيقات أو النظام. لا تغيّره إلا إذا كنت تعرف ما يفعله.",
