"Choose the sign-in method in the agent's Connect sheet. The tools are installed into a Debian environment inside Termux when they have no Android build. This takes several minutes and up to about 1 GB; the providers do not support Android officially, so a tool may not run on every phone.": "اختر طريقة تسجيل الدخول في نافذة الاتصال الخاصة بالوكيل. تُثبَّت الأدوات في بيئة Debian داخل Termux إذا لم يكن لها إصدار لنظام Android. يستغرق ذلك عدة دقائق وقد يصل حجمه إلى نحو 1 GB؛ والمزوّدون لا يدعمون Android رسميًا، لذا قد لا تعمل أداة ما على كل هاتف.",
"Choose what the extra button on each row of the Apps list does. It is always an icon, and the ones that change with the app (Enable / Disable, Install / Uninstall, Unsuspend / Suspend) switch their icon and action to match the app's current state.": "اختر ما يفعله الزر الإضافي في كل صف من قائمة التطبيقات. يكون دائمًا أيقونة، وتلك التي تتغير بحسب التطبيق (تفعيل / تعطيل، تثبيت / إلغاء التثبيت، إلغاء التعليق / تعليق) تبدّل أيقونتها وإجراءها بما يناسب حالة التطبيق الحالية.",
"Choose what to install and which starter files to write": "اختر ما تريد تثبيته وأي ملفات بدء تُكتب",
"Choosing a folder needs the app build": "اختيار مجلد يتطلب إصدار app",
"Choosing files works in the app": "يعمل اختيار الملفات في التطبيق",
"Chosen:": "المختار:",
"Classic three-button navigation bar": "شريط التنقل الكلاسيكي بثلاثة أزرار",
"Claude": "Claude",
"Claude (Anthropic)": "Claude (Anthropic)",
"Claude Code": "Claude Code",
"Claude Pro or Max and a Google account login may only be used in the providers' own apps: Anthropic and Google do not allow other apps to use those logins. So the Terminal signs you in through the official command-line tools running in Termux, where the provider's own website login opens:": "لا يمكن استخدام اشتراك Claude Pro أو Max وتسجيل الدخول بحساب Google إلا في تطبيقات المزوّدين أنفسهم: فـ Anthropic وGoogle لا تسمحان للتطبيقات الأخرى باستخدام عمليات تسجيل الدخول هذه. لذلك تُسجّل الطرفية دخولك عبر أدوات سطر الأوامر الرسمية التي تعمل في Termux، حيث تُفتح صفحة تسجيل الدخول على موقع المزوّد نفسه:",
"Clean up what is not needed any more: superfluous files, the expendable data of apps, the leftovers of apps that are gone, and files that exist twice. Scan first, look at the list, take out what you want to keep, then delete. The four tools use the working mode of this app for the folders a normal app cannot read.": "نظّف ما لم تعد بحاجة إليه: الملفات الزائدة، والبيانات التي يمكن الاستغناء عنها للتطبيقات، وبقايا التطبيقات المحذوفة، والملفات الموجودة مرتين. افحص أولًا، وانظر إلى القائمة، وأزل ما تريد الاحتفاظ به، ثم احذف. تستخدم الأدوات الأربع وضع تشغيل هذا التطبيق للمجلدات التي لا يستطيع التطبيق العادي قراءتها.",
"Clean — no engine flagged this file": "سليم — لم يُبلغ أي محرك فحص عن هذا الملف",
"Cleanup is simulated. Files are scanned and reported, but nothing is actually deleted.": "التنظيف محاكى. تُفحص الملفات ويُبلَّغ عنها، لكن لا يُحذف شيء فعليًا.",
