"Commands run as Termux, in its home folder, with your Termux packages and (with Match my Termux environment on) your aliases and functions too. Sync with Termux also opens Termux so you can grant it access to shared storage.": "تُنفَّذ الأوامر بصفة Termux، في مجلده الرئيسي، مع حزم Termux الخاصة بك (ومع تشغيل «مطابقة بيئة Termux الخاصة بي» تتاح لك أيضًا الأسماء المستعارة والدوال). تفتح «المزامنة مع Termux» كذلك Termux لتتمكن من منحه حق الوصول إلى التخزين المشترك.",
