"Draw the app icons in the list with an icon pack you have installed (ADW, Nova, Apex and Go packs). Apps the pack does not cover get the pack's background and shape when it has one, and otherwise keep their own icon.": "اعرض أيقونات التطبيقات في القائمة بحزمة أيقونات ثبّتها (حزم ADW وNova وApex وGo). التطبيقات التي لا تشملها الحزمة تحصل على خلفية الحزمة وشكلها إن وُجدا، وإلا فتحتفظ بأيقونتها الخاصة.",
"Droid-ify": "Droid-ify",
"DroidMind": "DroidMind",
"DroidMind is an MCP server: a tool that gives AI agents control of an Android device over ADB (apps, files, logs, screenshots). It is not a chat by itself.": "DroidMind خادم MCP: أداة تمنح وكلاء الذكاء الاصطناعي التحكم في جهاز Android عبر ADB (التطبيقات والملفات والسجلات ولقطات الشاشة). وهو ليس دردشة بحد ذاته.",
"DroidMind is installed in Debian. Start it with: proot-distro login debian -- ~/.local/bin/droidmind --transport sse. Add it to your agent as an MCP server (its address is printed when it starts).": "تم تثبيت DroidMind في Debian. شغّله بالأمر: proot-distro login debian -- ~/.local/bin/droidmind --transport sse. أضفه إلى وكيلك بوصفه خادم MCP (يُطبع عنوانه عند بدء التشغيل).",
