"EXPERT": "خبير",
"Each agent keeps this in its own file, the same way its official sign-in does, so two or more agents can carry the same server and either can be used with it. Codex keeps a remote server's token as an environment variable instead of in its file. Not tested against every version of every tool.": "يحتفظ كل وكيل بهذا في ملفه الخاص، بالطريقة نفسها التي يعمل بها تسجيل الدخول الرسمي، لذا يمكن لوكيلين أو أكثر أن يحملا الخادم نفسه ويمكن استخدام أيٍّ منهما معه. يحتفظ Codex برمز الخادم البعيد كمتغير بيئة بدلًا من ملفه. لم يُختبر مع كل إصدار من كل أداة.",
"Each shell keeps its own screen and stays open while you use other tabs: cd, export and variables carry over from one command to the next. Restart shell starts a fresh one.": "يحتفظ كل Shell بشاشته الخاصة ويبقى مفتوحًا أثناء استخدامك لتبويبات أخرى: ينتقل أثر cd وexport والمتغيرات من أمر إلى الأمر التالي. ويبدأ «إعادة تشغيل Shell» جلسة جديدة.",
"Each wait is 600 seconds (10 minutes) at most.": "مدة كل انتظار 600 ثانية (10 دقائق) كحد أقصى.",
"Earlier certificates (the signing key was changed)": "الشهادات السابقة (تم تغيير مفتاح التوقيع)",
"Edit": "تعديل",
"Edit Saved List": "تعديل القائمة المحفوظة",
