"Edit text": "تعديل النص",
"Edited": "المعدّلة",
"Editing an APK changes its contents, so its signature no longer matches. Android will not install it until it is signed again: use Sign (this app signs with a key of its own).": "يؤدي تعديل APK إلى تغيير محتوياته، فلا يعود توقيعه مطابقًا. لن يثبّته Android قبل توقيعه من جديد: استخدم «توقيع» (يوقّع هذا التطبيق بمفتاح خاص به).",
"Editing an APK changes its contents, so its signature no longer matches. Android will not install it until it is signed again; Sign does that with a key of this app.": "يؤدي تعديل APK إلى تغيير محتوياته، فلا يعود توقيعه مطابقًا. لن يثبّته Android قبل توقيعه من جديد؛ ويتولى «توقيع» ذلك بمفتاح خاص بهذا التطبيق.",
"Effort": "الجهد",
"Effort only changes anything for the agents whose own API has that knob (Claude, ChatGPT, Gemini, Grok); for the others it is kept but has no effect when chatting by API key, and none of them pass it on to their own sign-in tool in Termux.": "لا يغيّر «الجهد» شيئًا إلا مع الوكلاء الذين تتضمن واجهة API الخاصة بهم هذا الخيار (Claude وChatGPT وGemini وGrok)؛ أما مع غيرهم فيُحفظ دون أي تأثير عند الدردشة بمفتاح API، ولا يمرّره أي منهم إلى أداة تسجيل الدخول الخاصة به في Termux.",
