"Error": "خطأ",
"Error:": "خطأ:",
"Error: Connected Devices works in the app, not in a plain browser.": "خطأ: تعمل «الأجهزة المتصلة» في التطبيق، وليس في متصفح عادي.",
"Error: choose a device first": "خطأ: اختر جهازًا أولًا",
"Error: the command could not be started": "خطأ: تعذّر بدء الأمر",
"Errors": "الأخطاء",
"Errors only": "الأخطاء فقط",
"Every app in the F-Droid catalog, or in any of the known third-party repositories. Pick a repository, browse by category and install directly — downloads are checked against the repository's published SHA-256.": "كل تطبيق في فهرس F-Droid أو في أي من مستودعات الطرف الثالث المعروفة. اختر مستودعًا وتصفّح حسب الفئة وثبّت مباشرةً — يتم التحقق من التنزيلات مقابل قيمة SHA-256 المنشورة في المستودع.",
"Every app that is not enabled is saved.": "يتم حفظ كل تطبيق غير مفعّل.",
"Every change goes into the history, so it can be reverted.": "يُسجَّل كل تغيير في السجل، لذا يمكن التراجع عنه.",
"Every level is hidden - tap the color key above to show some.": "جميع المستويات مخفية - انقر على دليل الألوان أعلاه لإظهار بعضها.",
