"Found by reading the class names in the app's code on this phone; nothing is sent anywhere. Tracker list: Exodus Privacy, licensed ODbL 1.0. Code renamed by a shrinker (R8, ProGuard) or loaded later can hide a tracker, so a low number is not proof that there are none.": "عُثر عليها بقراءة أسماء الفئات في شيفرة التطبيق على هذا الهاتف؛ لا يُرسل شيء إلى أي مكان. قائمة أدوات التتبع: Exodus Privacy، بترخيص ODbL 1.0. قد تخفي الشيفرة التي أعاد مُصغِّر (R8 أو ProGuard) تسميتها أو التي تُحمَّل لاحقًا أداة تتبع، فالرقم المنخفض ليس دليلًا على عدم وجود أي منها.",
