"From File Manager: installing through a privileged backend, with this app's signature checks off. Android still verifies signatures itself: an APK whose signature it can't verify is signed with this app's key and installed, and an app signed by someone else can only be replaced after uninstalling it (you are asked first).": "من مدير الملفات: التثبيت عبر واجهة خلفية ذات صلاحيات، مع إيقاف فحوصات التوقيع الخاصة بهذا التطبيق. ما زال Android يتحقق من التوقيعات بنفسه: يُوقَّع أي APK لا يستطيع التحقق من توقيعه بمفتاح هذا التطبيق ثم يُثبَّت، ولا يمكن استبدال تطبيق وقّعه طرف آخر إلا بعد إلغاء تثبيته (يُطلب منك التأكيد أولًا).",
