"Hands the queued files to Android's Bluetooth sharing, which asks which paired device gets them. Most watches, Wear OS included, cannot receive files this way: for a Wear OS watch use the Bluetooth link under Add device and send over ADB instead.": "يسلّم الملفات الموجودة في قائمة الانتظار إلى مشاركة Bluetooth في Android، التي تسأل عن الجهاز المقترن الذي سيستلمها. لا تستطيع معظم الساعات، ومنها Wear OS، استلام الملفات بهذه الطريقة: لساعة Wear OS استخدم اتصال Bluetooth ضمن «إضافة جهاز» وأرسل عبر ADB بدلًا من ذلك.",
