"Invalid source URL: the address must point to a GitHub or GitLab repository, or to a .json metadata file.": "عنوان URL للمصدر غير صالح: يجب أن يشير العنوان إلى مستودع GitHub أو GitLab، أو إلى ملف بيانات وصفية بصيغة .json.",
