"Jan runs AI models on your computer, free. On the computer: Jan, Settings, Local API Server: set the host to 0.0.0.0 and start it, then enter the computer's address here (like http://192.168.1.20:1337/v1). There is no Android version of Jan.": "يشغّل Jan نماذج الذكاء الاصطناعي على حاسوبك مجانًا. على الحاسوب: Jan، ثم Settings، ثم Local API Server: اضبط المضيف على 0.0.0.0 وشغّله، ثم أدخل عنوان الحاسوب هنا (مثل http://192.168.1.20:1337/v1). لا يوجد إصدار من Jan لنظام Android.",
