"Keeps its data (install -r)": "يحتفظ ببياناته (install -r)",
"Keeps only the libraries for this phone's CPU. Needs less memory and makes a smaller APK.": "يُبقي فقط على المكتبات الخاصة بمعالج هذا الهاتف. يحتاج ذاكرة أقل وينتج ملف APK أصغر.",
