"Keyboard": "لوحة المفاتيح",
"Keys and servers": "المفاتيح والخوادم",
"Keys are encrypted with a key that stays in the phone's secure hardware, and they are only ever sent to their own provider's address. The page never sees them again after you type them; only the last four characters are shown.": "تُشفَّر المفاتيح بمفتاح يبقى في العتاد الآمن للهاتف، ولا تُرسَل أبدًا إلا إلى عنوان مزوّدها. لا تراها الصفحة مجددًا بعد أن تكتبها؛ ولا يظهر منها إلا آخر أربعة أحرف.",
"Keys, default agent and model, shells, and what agents may do without asking": "المفاتيح، والوكيل والنموذج الافتراضيان، وأنواع Shell، وما يمكن للوكلاء فعله دون استئذان",
