"Lenovo": "Lenovo",
"Leon is an open-source personal assistant (skills, voice) that runs on a computer with Node.js and Python. It has no Android version and is not a coding agent, so it does not chat in this Terminal.": "Leon مساعد شخصي مفتوح المصدر (مهارات وصوت) يعمل على حاسوب مع Node.js وPython. ليس له إصدار لنظام Android وليس وكيل برمجة، لذا لا يدردش في هذه الطرفية.",
"Leon.ai": "Leon.ai",
"Let Termux take commands from other apps": "السماح لـ Termux بتلقّي الأوامر من التطبيقات الأخرى",
"Let them act without asking": "السماح لها بالتصرف دون استئذان",
"Lets the agent read and write files under the folder named at the end of the command (change /sdcard to taste).": "يتيح للوكيل قراءة الملفات وكتابتها داخل المجلد المذكور في نهاية الأمر (غيّر /sdcard كما تشاء).",
"Lets the agent think in explicit steps before it acts.": "يتيح للوكيل التفكير في خطوات صريحة قبل أن يتصرف.",
"Lets this app change a few protected system settings used by some advanced features.": "يتيح لهذا التطبيق تغيير بعض إعدادات النظام المحمية التي تستخدمها بعض الميزات المتقدمة.",
"Lets this app install the package files you choose, such as APK, APKS and XAPK files from your storage.": "يتيح لهذا التطبيق تثبيت ملفات الحزم التي تختارها، مثل ملفات APK وAPKS وXAPK من مساحة التخزين لديك.",
"Lets this app open another app's screen from the background, such as an app you have just installed.": "يتيح لهذا التطبيق فتح شاشة تطبيق آخر من الخلفية، مثل تطبيق ثبّتّه للتو.",
