"Off": "إيقاف",
"Off by default": "متوقف افتراضيًا",
"Off:": "متوقف:",
"Off: reading outside the current folder needs your OK.": "عند الإيقاف: تحتاج القراءة خارج المجلد الحالي إلى موافقتك.",
"Off: the patches that work are applied and the failed ones are reported.": "متوقف: تُطبَّق التصحيحات التي تعمل ويُبلَّغ عن الفاشلة.",
