"Offline cache": "ذاكرة التخزين المؤقت دون اتصال",
"Offline: showing what was loaded": "دون اتصال: عرض ما تم تحميله",
"Old": "القديم",
"Older version": "إصدار أقدم",
"Ollama": "Ollama",
"Ollama (on-device)": "Ollama (على الجهاز)",
"Ollama is not running on this phone yet. Install it below, or enter the address of a computer that runs it.": "لا يعمل Ollama على هذا الهاتف بعد. ثبّته أدناه، أو أدخل عنوان حاسوب يشغّله.",
"Ollama runs a coding model right on this phone: free, and offline once the model is downloaded. It is installed in Termux; small models (1.5B to 3B) run best on a phone.": "يشغّل Ollama نموذج برمجة على هذا الهاتف مباشرةً: مجانًا، ودون اتصال بالإنترنت بعد تنزيل النموذج. يُثبَّت في Termux؛ وتعمل النماذج الصغيرة (من 1.5B إلى 3B) بشكل أفضل على الهاتف.",
"On": "تشغيل",
"On device": "على الجهاز",
"On this phone": "على هذا الهاتف",
"On:": "مفعّل:",
"One command at a time per shell; long output is trimmed on screen and in what is sent to an agent.": "أمر واحد في كل مرة لكل Shell؛ وتُقتطع المخرجات الطويلة على الشاشة وفيما يُرسل إلى الوكيل.",
"One file only": "ملف واحد فقط",
"One key for the whole app. The Installer's scan and Morphe Helper's scan both use it; neither asks for it again, they only point here when it is missing.": "مفتاح واحد للتطبيق كله. يستخدمه فحص المثبّت وفحص Morphe Helper؛ ولا يطلبه أي منهما مجددًا، بل يشيران إلى هنا فقط عندما يكون مفقودًا.",
"One more place to find apps": "مكان آخر للعثور على التطبيقات",
"One package per line. Duplicate entries are removed automatically.": "حزمة واحدة في كل سطر. تتم إزالة الإدخالات المكررة تلقائيًا.",
"One source color, nine ways to turn it into a whole theme: the accent, the background, the cards and the text, in light and in dark. Choosing a style builds the theme from the source color below.": "لون مصدر واحد وتسع طرق لتحويله إلى سمة كاملة: اللون المميّز والخلفية والبطاقات والنص، في الوضعين الفاتح والداكن. اختيار نمط يبني السمة من اللون المصدر أدناه.",
"Only AppCleaner uses it: it opens the system's App info screen of each app and taps Clear cache, for the caches no file access can reach. It does nothing else, never reads what is on the screen apart from those screens, and stops when the screen turns off.": "يستخدمه AppCleaner فقط: يفتح شاشة معلومات التطبيق في النظام لكل تطبيق ويضغط على مسح ذاكرة التخزين المؤقت، للذاكرات المؤقتة التي لا يصل إليها أي وصول إلى الملفات. لا يفعل شيئًا آخر، ولا يقرأ ما على الشاشة سوى تلك الشاشات، ويتوقف عند انطفاء الشاشة.",
"Only a marked block is written to these files; what you have in them stays, and running this again refreshes the block instead of adding another.": "لا يُكتب في هذه الملفات سوى كتلة معلَّمة؛ وما لديك فيها يبقى، وتشغيل هذا مجددًا يحدّث الكتلة بدل إضافة أخرى.",
"Only add sources you trust. A patch source decides what ends up inside your patched apps.": "أضف المصادر التي تثق بها فقط. يحدد مصدر التصحيحات ما ينتهي داخل تطبيقاتك المصحَّحة.",
"Only apps installed on this phone": "التطبيقات المثبّتة على هذا الهاتف فقط",
"Only base": "الأساسي فقط",
"Only hidden files are here. Tick Show hidden files to see them.": "الملفات الموجودة هنا مخفية فقط. حدّد «عرض الملفات المخفية» لرؤيتها.",
"Only include common media files, documents and archives.": "تضمين ملفات الوسائط والمستندات والأرشيفات الشائعة فقط.",
"Only list what would run for each app. Nothing is run.": "عرض ما سيُنفَّذ لكل تطبيق فقط. لا يُنفَّذ أي شيء.",
"Only patches for apps installed on this phone": "تصحيحات التطبيقات المثبّتة على هذا الهاتف فقط",
"Only text and compiled XML files can be compared line by line": "يمكن مقارنة الملفات النصية وملفات XML المُجمَّعة سطرًا بسطر فقط",
"Only the lines written by the app you pick": "الأسطر التي كتبها التطبيق الذي تختاره فقط",
"Only the selected apps are saved.": "يتم حفظ التطبيقات المحددة فقط.",
"Only the text of this app changes; names, paths and commands in code-style boxes keep their own font.": "يتغيّر نص هذا التطبيق فقط؛ أما الأسماء والمسارات والأوامر في مربعات الأكواد فتحتفظ بخطها.",
