"Phone makers and apps add settings of their own.": "تضيف الشركات المصنّعة للهواتف والتطبيقات إعداداتها الخاصة.",
"Pick a .mpp patch bundle from storage. A local source never updates on its own: pick the new file when one comes out.": "اختر حزمة تصحيحات .mpp من التخزين. المصدر المحلي لا يتحدّث من تلقاء نفسه: اختر الملف الجديد عند صدوره.",
