"Pick a package first": "اختر حزمة أولًا",
"Pick an agent under Coding Agents to chat": "اختر وكيلًا من «وكلاء البرمجة» للدردشة",
"Pick an agent, then the model and the effort (Low, Balanced or High: how hard it is asked to think). The first time, both start at a balanced choice, and the agent asks for what it needs (an API key, a server address, or a sign-in) and tests it before you start.": "اختر وكيلًا، ثم النموذج والجهد (منخفض أو متوازن أو مرتفع: مقدار الجهد الذهني المطلوب منه). في المرة الأولى يبدأ كلاهما باختيار متوازن، ويطلب الوكيل ما يحتاج إليه (مفتاح API أو عنوان خادم أو تسجيل دخول) ويختبره قبل أن تبدأ.",
"Pick at least one agent": "اختر وكيلًا واحدًا على الأقل",
"Pick at least one patch": "اختر تصحيحًا واحدًا على الأقل",
"Pick one to fill the fields below, or write your own": "اختر واحدًا لملء الحقول أدناه، أو اكتب إعدادك الخاص",
"Pick which split APKs to install. The base APK is always included, and every other split starts ticked because \"Select all splits by default\" is on.": "اختر ملفات APK المجزّأة المراد تثبيتها. يتم تضمين APK الأساسي دائمًا، وتبدأ جميع الأجزاء الأخرى محددة لأن خيار «تحديد جميع الأجزاء افتراضيًا» مفعّل.",
"Pick which split APKs to install. The base APK is always included; the splits that fit this phone are ticked and the others are left off for you to add.": "اختر ملفات APK المجزّأة المراد تثبيتها. يتم تضمين APK الأساسي دائمًا؛ وتُحدَّد الأجزاء المناسبة لهذا الهاتف وتُترك البقية دون تحديد لتضيفها بنفسك.",
