"System related temporary files (e.g. from Android Studio).": "ملفات مؤقتة متعلقة بالنظام (مثل ملفات Android Studio).",
"System related temporary files, usually short lived caches for active operations.": "ملفات مؤقتة متعلقة بالنظام، وعادةً ذاكرات مؤقتة قصيرة العمر للعمليات النشطة.",
"System service specific log files.": "ملفات سجل خاصة بخدمات النظام.",
