"Tabs are back in their default order, all turned on": "عادت التبويبات إلى ترتيبها الافتراضي، وجميعها مفعّلة",
"Take a screenshot": "التقاط لقطة شاشة",
"TalkBack touch exploration": "الاستكشاف باللمس في TalkBack",
"Tap": "انقر",
"Tap All to clear.": "انقر على «الكل» للمسح.",
"Tap Check for Updates.": "انقر على «التحقق من وجود تحديثات».",
"Tap a color to copy it. Android 12+ derives these from one source color.": "انقر على لون لنسخه. يشتق Android 12+ هذه الألوان من لون مصدر واحد.",
"Tap a command to drop it in the input. These run in the on-device shell — no adb shell prefix needed.": "انقر على أمر لإدراجه في حقل الإدخال. تُنفَّذ هذه في Shell الجهاز — دون الحاجة إلى البادئة adb shell.",
"Tap a picture to enlarge it.": "اضغط على صورة لتكبيرها.",
"Tap a topic to open it. Tap": "انقر على موضوع لفتحه. انقر على",
"Tap at coordinates": "النقر على إحداثيات",
"Tap the button below, then allow the connection on the watch.": "انقر على الزر أدناه، ثم اسمح بالاتصال على الساعة.",
"Tap to load it · press and hold (or press Delete) to delete it": "انقر لتحميله · اضغط مطولًا (أو اضغط Delete) لحذفه",
"Tap: batch actions · Hold: clear selection": "انقر: الإجراءات الجماعية · اضغط مطولًا: مسح التحديد",
