"To search storage for APK, APKS, APKM and XAPK files, this app needs All-files access (or a working mode: ADB, Shizuku or Root).": "للبحث في وحدة التخزين عن ملفات APK وAPKS وAPKM وXAPK، يحتاج هذا التطبيق إلى «الوصول إلى جميع الملفات» (أو وضع تشغيل: ADB أو Shizuku أو Root).",
