"When a Wi-Fi sign-in page is found (0 ignore, 1 ask, 2 avoid the network)": "عند العثور على صفحة تسجيل دخول Wi-Fi (0 تجاهل، 1 سؤال، 2 تجنّب الشبكة)",
"When deleting duplicates, SD Maid decides which file to keep by checking each criterion in order. The first criterion that produces a clear winner determines the result. Drag to reorder, tap to change mode.": "عند حذف المكرّرات يقرر SD Maid أي ملف يُبقي بفحص كل معيار بالترتيب. المعيار الأول الذي ينتج فائزًا واضحًا يحدد النتيجة. اسحب لإعادة الترتيب، واضغط لتغيير الوضع.",
"When the chosen source does not have the version or does not work, This version, Newest and All versions go on with the next source, in the order above, until one delivers.": "عندما لا يملك المصدر المختار الإصدار أو لا يعمل، تنتقل «هذا الإصدار» و«الأحدث» و«كل الإصدارات» إلى المصدر التالي بالترتيب أعلاه حتى ينجح أحدها.",
"Where the whole palette comes from": "مصدر لوحة الألوان بالكامل",
