"Wireless debugging is not announcing this device. Turn Wireless debugging off and on on the device (same Wi-Fi), then try again.": "تصحيح الأخطاء اللاسلكي لا يعلن عن هذا الجهاز. أوقف تصحيح الأخطاء اللاسلكي وشغّله على الجهاز (نفس Wi-Fi) ثم حاول مجددًا.",
"Withdraw consent": "سحب الموافقة",
"Without it AppCleaner still deletes every cache it can reach with file access and, with a working mode, trims the caches of all apps at once.": "بدونها يظل AppCleaner يحذف كل ذاكرة مؤقتة يصل إليها بالوصول إلى الملفات، ومع وضع تشغيل يقلّص ذاكرات كل التطبيقات دفعة واحدة.",
