"Write an absolute path, like /storage/emulated/0/DCIM": "اكتب مسارًا مطلقًا مثل /storage/emulated/0/DCIM",
"Write at least one number of seconds, like 0, 8, 25.": "اكتب رقمًا واحدًا على الأقل من الثواني مثل 0 و8 و25.",
"Write the name segments, like DCIM/Camera": "اكتب مقاطع الاسم مثل DCIM/Camera",
"Write the starter ~/.bashrc": "كتابة ملف ~/.bashrc الأولي",
"Write the starter ~/.nanorc": "كتابة ملف ~/.nanorc الأولي",
"Write the starter ~/.vimrc": "كتابة ملف ~/.vimrc الأولي",
"Write your message first.": "اكتب رسالتك أولًا.",
"XAPK": "XAPK",
"Xiaomi": "Xiaomi",
"Xiaomi GetApps": "Xiaomi GetApps",
"Yellow": "أصفر",
"Yes": "نعم",
"You can grant or revoke it here.": "يمكنك منحه أو إلغاءه هنا.",
"You edited this APK, so its signature is no longer valid and Android will not install it as it is.": "لقد عدّلت هذا APK، لذا لم يعد توقيعه صالحًا ولن يثبّته Android كما هو.",
"You explain one Android hidden setting (an entry of the Settings.Global, Settings.Secure or Settings.System database, the ones \"settings get/put\" reads and writes) to someone who is not a developer.": "أنت تشرح إعدادًا مخفيًا واحدًا في Android (إدخال في قاعدة بيانات Settings.Global أو Settings.Secure أو Settings.System، تلك التي يقرؤها ويكتبها «settings get/put») لشخص ليس مطوّرًا.",
"You explain one Android hidden setting (an entry of the Settings.Global, Settings.Secure or Settings.System database, the ones \"settings get/put\" reads and writes) to someone who is not a developer. Say briefly: what it controls, what its values mean, what changing it does, and whether it is safe to change. Say plainly when you do not know the setting (many belong to the phone maker) instead of guessing, and then say what its name suggests. Short paragraphs, no headings.": "أنت تشرح إعدادًا مخفيًا واحدًا في Android (إدخال في قاعدة بيانات Settings.Global أو Settings.Secure أو Settings.System، تلك التي يقرؤها ويكتبها «settings get/put») لشخص ليس مطوّرًا. قل باختصار: ما الذي يتحكم فيه، وما معنى قيمه، وماذا يحدث عند تغييره، وهل تغييره آمن. قل بوضوح إذا كنت لا تعرف الإعداد (كثير منها يخص الشركة المصنّعة للهاتف) بدل التخمين، ثم قل ما يوحي به اسمه. فقرات قصيرة، بلا عناوين.",
"You explain one Android logcat entry to someone who is not a developer. Say, in plain words and briefly: what this line means,": "أنت تشرح إدخالًا واحدًا من logcat في Android لشخص ليس مطوّرًا. قل بكلمات بسيطة وباختصار: ما معنى هذا السطر،",
"You explain one Android logcat entry to someone who is not a developer. Say, in plain words and briefly: what this line means, the most likely cause, whether it matters (harmless noise, a real problem, or a crash) and, if it does matter, what to try. Use short paragraphs, no headings. If the line is too cryptic to explain with confidence, say so and say what else would help. Do not invent details.": "أنت تشرح إدخالًا واحدًا من logcat في Android لشخص ليس مطوّرًا. قل بكلمات بسيطة وباختصار: ما معنى هذا السطر، والسبب الأرجح، وهل هو مهم (ضجيج غير ضار أم مشكلة حقيقية أم عطل) وإن كان مهمًا فماذا يمكن تجربته. استخدم فقرات قصيرة بلا عناوين. إذا كان السطر غامضًا جدًا بحيث لا يمكن شرحه بثقة فقل ذلك وبيّن ما الذي سيساعد أيضًا. لا تختلق تفاصيل.",
"You help with ADB and shell command syntax in an Android terminal. Answer briefly and practically.": "أنت تساعد في ADB وصيغة أوامر Shell في طرفية Android. أجب بإيجاز وبشكل عملي.",
"You help with ADB and shell command syntax in an Android terminal. Answer briefly and practically. If you want to propose exactly one command for the user to run here, put it by itself inside": "أنت تساعد في ADB وصيغة أوامر Shell في طرفية Android. أجب بإيجاز وبشكل عملي. إذا أردت اقتراح أمر واحد فقط ليُنفّذه المستخدم هنا، فضعه وحده داخل",
"You're on a metered connection (mobile data / hotspot).": "أنت متصل عبر شبكة محدودة (بيانات الجوّال / نقطة الاتصال).",
