"v1 is the old signature kept in the META-INF folder. v2, v3 and v3.1 sit in the APK signing block; v3 and v3.1 allow the signing key to be changed later. The base APK is the one read.": "v1 هو التوقيع القديم المحفوظ في مجلد META-INF. أما v2 وv3 وv3.1 فتقع في كتلة توقيع APK؛ ويتيح v3 وv3.1 تغيير مفتاح التوقيع لاحقًا. المقروء هو APK الأساسي.",
